<?php

namespace ModulesGarden\TSSGGSModule\App\Libs\Support;

/**
 * Inline SVG icons (Material Design Icons, path data in IconPaths.php, generated by tools/gen-icons.js).
 * The icon is a 24x24 viewBox drawn in the current text colour; its box is 16px unless the CSS of the place sets
 * another fixed size on .tssggs-ico.
 */
class Icons
{
    protected static $paths = null;

    /**
     * Brand icons that are not Material Design Icons: name => [viewBox, path data], drawn the same way (current text
     * colour, the box of .tssggs-ico). getlei: the GetLEI shield (my.gogetssl.com front_map.svg, "getlei-symbol").
     */
    const CUSTOM = [
        'getlei' => ['0 0 26 32', 'M7.208 17.045V7.005L3.876 8.398v9.691c0 5.45 4.324 7.346 4.369 7.365l4.676 1.978 4.766-1.978c.002-.001.063-.02.14-.057l-4.906-2.03-2.703-1.154c-.126-.053-3.01-1.326-3.01-5.168zm1.587 0c0 2.353 1.89 3.178 1.909 3.186l2.217.935 4.284 1.74v-4.064l-4.284-1.74V14.89l4.284 1.75v-4.065l-4.284-1.74V8.624l4.284 1.75V6.31L12.92 4.57l-4.126 1.74v10.736zm13.329-8.647l-3.332-1.393v16.598l.954.4c1.155-1.13 2.378-3.012 2.378-5.914v-9.69zM12.153.44L6.322 2.876l-4.99 2.089L.066 5.5V18.09c0 2.87.847 5.534 2.472 7.705 1.187 1.585 2.82 2.92 4.378 3.57l5.24 2.198.764.334.838-.334 5.293-2.198c.101-.042 1.106-.465 2.302-1.408a11.736 11.736 0 0 0 1.911-1.9c1.77-2.21 2.668-4.89 2.668-7.967V5.5l-1.281-.535-5.01-2.09L13.793.455l-.838-.321h-.035V.104l-.768.335zm.768 29.194l-5.242-2.198C5.747 26.63 2.13 23.64 2.13 18.089V6.893l5.014-2.159h-.036l5.813-2.367 5.884 2.367h.025l5.04 2.159v11.196c0 3.052-1.051 5.21-2.23 6.677 0 0-.6.786-1.567 1.55-.968.763-1.803 1.105-1.84 1.12l-5.312 2.197z'],
    ];

    /**
     * @param string $name icon name ("check", "mdi-check" and "mdi mdi-check" are all accepted)
     * @return string the <svg> element, '' for an unknown icon
     */
    public static function svg(string $name, string $class = ''): string
    {
        if(self::$paths === null)
        {
            self::$paths = require __DIR__ . '/IconPaths.php';
        }

        $name = preg_replace('/^.*\bmdi-/', '', trim($name));
        if(isset(self::CUSTOM[$name]))
        {
            [$viewBox, $path] = self::CUSTOM[$name];
        }
        elseif(isset(self::$paths[$name]))
        {
            [$viewBox, $path] = ['0 0 24 24', self::$paths[$name]];
        }
        else
        {
            return '';
        }

        return '<svg class="tssggs-ico tssggs-ico--' . $name . ($class !== '' ? ' ' . $class : '') . '" viewBox="' . $viewBox . '" width="16" height="16" aria-hidden="true" focusable="false">'
            . '<path fill="currentColor" d="' . $path . '"/></svg>';
    }
}
